    set<int> a={1,2,3},b={2,3,4};
    set<int> uni=a,inter,diff;
    for (int x:b)uni.insert(x);
    for (int x:a){
        if (b.count(x))inter.insert(x);
        else diff.insert(x);
    }
    for (int x:uni)cout<<x<<" ";
    cout<<"\n";
    for (int x:inter)cout<<x<<" ";
    cout<<"\n";
    for (int x:diff)cout<<x<<" ";
    cout<<"\n";
    return 0;
}

